      try{ statsTap({ id: hs.id + ':' + k }); }catch(x){}
      leg.textContent = z.texte ? trJeu(z.texte) : trJeu(z.label || '');
      b.classList.remove('touche'); void b.offsetWidth; b.classList.add('touche', 'vue');
