  const x = mk('button', 'pnl-close', '\u2715');
  x.type = 'button'; x.setAttribute('aria-label', 'Fermer');
  x.onclick = function(e){ e.stopPropagation(); fond.remove(); };
  fond.appendChild(x);
  frameEl.appendChild(fond);
