    Object.keys(cats).forEach(function(c){
      corps.appendChild(PlayerUI.mk('div', { fontWeight: '600', margin: '10px 0 4px' })).textContent = trJeu(c);
      cats[c].forEach(function(f){
        const o = cdxOuverte(f), b = PlayerUI.button(o ? trJeu(f.titre || '') : '? ? ?', function(){ if(o) fiche(f); });
        b.style.display = 'block'; b.style.width = '100%'; b.style.textAlign = 'left'; b.disabled = !o; if(!o) b.style.opacity = '.45';
        corps.appendChild(b);
      });
    });
